            has_pre = False
            for other in nodes:
                if other != node and node in closure[other]:
                    has_pre = True
                    break
            if not has_pre:
                u = node
                break
        res = count_fast(frozenset(nodes - {u})) + \
               count_fast(frozenset(nodes - closure[u]))
        memo_fast[nodes] = res
        return res

    print(f"Result: {count_fast(frozenset(range(num_sccs)))}")

solve()
